#include "DSP/SeptumEngine.h"
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <vector>

void word(std::ostream& stream, uint32_t x, int count = 4)
{ for (int i=0; i<count; ++i) stream.put(char((x >> (i*8)) & 255)); }
void wav(const std::string& path, const std::vector<float>& y)
{
    std::ofstream out(path, std::ios::binary);
    out.write("RIFF",4); word(out,36+uint32_t(y.size()*4)); out.write("WAVEfmt ",8);
    word(out,16); word(out,3,2); word(out,1,2); word(out,44100); word(out,44100*4);
    word(out,4,2); word(out,32,2); out.write("data",4); word(out,uint32_t(y.size()*4));
    out.write(reinterpret_cast<const char*>(y.data()),std::streamsize(y.size()*4));
}
int main(int argc,char**argv)
{
    if(argc!=2) return 2;
    constexpr int rate=44100;
    for(bool solo:{false,true}) for(bool moving:{false,true}) for(int slope:{12,24})
    {
        septum::Engine engine;
        auto calibration=septum::Engine::defaultTimbreCalibration();
        calibration.filterEnabled=true;
        calibration.secondStageIndependent=true;
        calibration.resonanceDamping.fill(1.2);
        calibration.secondStageDamping.fill(1.2);
        if(!engine.setTimbreCalibration(calibration)) return 3;
        engine.prepare(rate,256);
        septum::Patch patch;
        auto& tone=patch.upper;
        tone.osc1.wave=septum::Waveform::Saw;
        tone.balance=-63;
        tone.filterType=septum::FilterType::Lpf;
        tone.filterSlope=slope==12?septum::FilterSlope::Db12:septum::FilterSlope::Db24;
        tone.cutoff=34; tone.keyFollow=100;
        tone.resonance=tone.cutoffVelocitySens=0;
        tone.filterEnvAttack=0; tone.filterEnvDecay=63;
        tone.filterEnvSustain=moving?0:127; tone.filterEnvDepth=21; tone.filterEnvRelease=0;
        tone.level=50; tone.levelVelocitySens=0;
        tone.ampEnvAttack=0; tone.ampEnvDecay=0; tone.ampEnvSustain=127; tone.ampEnvRelease=0;
        tone.lfo1.depth1=tone.lfo1.depth2=tone.lfo2.depth1=tone.lfo2.depth2=0;
        patch.delayOn=patch.reverbOn=false;
        engine.setPatch(patch); engine.reset();
        const int chords[7][3]={{60,64,67},{48,52,55},{60,65,69},{48,53,57},{50,55,59},{60,64,67},{48,52,55}};
        const int targets[]={64,52,69,57,59,64,52};
        std::vector<float> left(14*rate),right(left.size());
        for(int i=0;i<7;++i)
        {
            if(solo) engine.noteOnDirect(targets[i],127);
            else for(int note:chords[i]) engine.noteOnDirect(note,127);
            engine.process(left.data()+i*2*rate,right.data()+i*2*rate,rate);
            if(solo) engine.noteOffDirect(targets[i]);
            else for(int note:chords[i]) engine.noteOffDirect(note);
            engine.process(left.data()+(i*2+1)*rate,right.data()+(i*2+1)*rate,rate);
        }
        const std::string name=std::string(solo?"target":"chord")+"-"+(moving?"dynamic":"static")+"-lp"+std::to_string(slope);
        wav(std::string(argv[1])+"/"+name+".wav",left);
        std::cout<<name<<" latency="<<engine.latencySamples()<<"\n";
    }
}
